import React from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import IncomingRequestListView from './IncomingRequestListView.tsx';
import InventoryView from './InventoryView.tsx';
import ExpiredBagsView from './ExpiredBagsView.tsx';
import './BloodBankView.css';

const BloodBankView = () => {
    return (
        <div>
            <h1>Blood Bank Dashboard</h1>
            <nav className="blood-bank-nav">
                <Link to="requests">Incoming Requests</Link>
                <Link to="inventory">Manage Inventory</Link>
                <Link to="expired">Expired Bags</Link>
            </nav>
            <div className="blood-bank-content">
                <Routes>
                    <Route path="requests" element={<IncomingRequestListView />} />
                    <Route path="inventory" element={<InventoryView />} />
                    <Route path="expired" element={<ExpiredBagsView />} />
                </Routes>
            </div>
        </div>
    );
};

export default BloodBankView;
